import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"Migrating from EssentialsX Kits","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/kits/migration-essentialsx.md","filePath":"en/modules/kits/migration-essentialsx.md","lastUpdated":0}`),a={name:`en/modules/kits/migration-essentialsx.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="migrating-from-essentialsx-kits" tabindex="-1">Migrating from EssentialsX Kits <a class="header-anchor" href="#migrating-from-essentialsx-kits" aria-label="Permalink to “Migrating from EssentialsX Kits”">​</a></h1><p>This page is for server owners moving from EssentialsX kits to EmakiKits. The mapping only covers documented ground (per the EssentialsX site and GitHub README); anything uncertain is marked TBC</p><h2 id="concept-mapping" tabindex="-1">Concept mapping <a class="header-anchor" href="#concept-mapping" aria-label="Permalink to “Concept mapping”">​</a></h2><table tabindex="0"><thead><tr><th>EssentialsX</th><th>EmakiKits</th><th>Notes</th></tr></thead><tbody><tr><td>One kit in <code>kits.yml</code></td><td>One kit in <code>kits/*.yml</code></td><td>EmakiKits keeps one kit per file; the id comes from the <code>id</code> field, not the file name</td></tr><tr><td>Kit item list</td><td><code>rewards.fixed</code></td><td>EmakiKits rewards use CoreLib item-source shorthands (<code>minecraft-bread</code> and friends), which differ from EssentialsX item syntax and need manual rewriting</td></tr><tr><td><code>delay</code> (seconds) cooldown</td><td>Cyclic kits / <code>max_claims_total</code></td><td>EssentialsX uses second-level cooldowns; EmakiKits approximates with <code>daily</code> / <code>weekly</code> / <code>monthly</code> period keys or a total cap. Second-level cooldowns are not supported (TBC)</td></tr><tr><td><code>delay: -1</code> one-time</td><td><code>max_claims_total: 1</code></td><td>The equivalent one-time kit</td></tr><tr><td>Kit permission</td><td>The kit&#39;s <code>permission</code> field</td><td>EssentialsX uses <code>essentials.kit.&lt;name&gt;</code> (check the EssentialsX docs); EmakiKits requires permissions to start with <code>emakikits.</code>, so rename nodes and update LuckPerms accordingly</td></tr></tbody></table><p>EssentialsX has no CDK, choice, invite, or cyclic kit concepts (not seen in the evidence gathered, which does not prove their absence). Those capabilities are net-new after migrating</p><h2 id="command-mapping" tabindex="-1">Command mapping <a class="header-anchor" href="#command-mapping" aria-label="Permalink to “Command mapping”">​</a></h2><table tabindex="0"><thead><tr><th>EssentialsX</th><th>EmakiKits</th></tr></thead><tbody><tr><td><code>/kit &lt;name&gt;</code></td><td><code>/ekits claim &lt;kitId&gt;</code></td></tr><tr><td><code>/kit list</code></td><td><code>/ekits list</code></td></tr><tr><td>(none)</td><td><code>/ekits preview &lt;kitId&gt;</code> before claiming</td></tr><tr><td>(none)</td><td><code>/ekits redeem &lt;kitId&gt; &lt;code&gt;</code> CDK redemption</td></tr></tbody></table><h2 id="data-migration" tabindex="-1">Data migration <a class="header-anchor" href="#data-migration" aria-label="Permalink to “Data migration”">​</a></h2><ul><li>EmakiKits keeps kit definitions in <code>plugins/EmakiKits/kits/*.yml</code> and runtime data in <code>plugins/EmakiKits/data/store.yml</code>; neither is compatible with EssentialsX <code>kits.yml</code> / userdata</li><li><strong>No automatic import</strong>: rewrite kit definitions manually per the tables above. Player cooldown records from EssentialsX cannot be imported; EmakiKits starts from empty records (preserving &quot;already claimed&quot; state has no tooling, TBC)</li></ul><h2 id="suggested-steps" tabindex="-1">Suggested steps <a class="header-anchor" href="#suggested-steps" aria-label="Permalink to “Suggested steps”">​</a></h2><ol><li>Install EmakiCoreLib + EmakiKits on a test server and rewrite each <code>kits.yml</code> entry into a <code>kits/*.yml</code> file (see the concept mapping)</li><li>Confirm loading with <code>/ekits check</code>, verify rewards with <code>/ekits preview</code></li><li>Switch permission nodes (replace <code>essentials.kit.*</code> with the matching <code>emakikits.*</code> nodes in LuckPerms) and verify claiming</li><li>Only after everything checks out, stop using the EssentialsX kits feature (other EssentialsX features are unaffected)</li></ol>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};